template:
% 参数由系统自动注入：\def\semimajor{2.4} \def\semiminor{2.0} \def\showcenter{1} \def\showaxes{1} \def\showasymptotes{1} \def\showfoci{1} \def\showvertices{1} \def\showpoint{0} \def\pointx{3.2} \def\labelp{P} \def\showcoord{1} \def\cx{0} \def\cy{0}
% 焦点距 c = sqrt(a^2 + b^2)
\pgfmathsetmacro{\focal}{sqrt(\semimajor*\semimajor + \semiminor*\semiminor)}
% 双曲线上点 P：由 x 求 y（右支，取正）：x^2/a^2 - y^2/b^2 = 1
\pgfmathsetmacro{\rpy}{\semiminor*sqrt(\pointx*\pointx/(\semimajor*\semimajor) - 1)}
% 视图宽度（含两侧分支与渐近线），坐标模式与裸图模式均需计算
\pgfmathsetmacro{\vieww}{max(1.4*\pointx, 1.4*\focal)}
% 双曲线绘图范围：x 从 a 附近到视图边界
\pgfmathsetmacro{\xmax}{\vieww/2}
% 渐近线延伸到视图边界的端点 y
\pgfmathsetmacro{\asymy}{\semiminor/\semimajor * \xmax}
% 视觉归一化：区分坐标模式与裸图模式
\ifnum\showcoord>0
  \pgfmathtruncatemacro{\xleft}{floor(\cx - \xmax - 0.8)}
  \pgfmathtruncatemacro{\xright}{ceil(\cx + \xmax + 0.8)}
  \pgfmathtruncatemacro{\ybottom}{floor(\cy - \asymy - 0.8)}
  \pgfmathtruncatemacro{\ytop}{ceil(\cy + \asymy + 0.8)}
  \pgfmathsetmacro{\xrange}{\xright - \xleft}
  \pgfmathsetmacro{\yrange}{\ytop - \ybottom}
  \pgfmathsetmacro{\figscale}{6.0 / max(\xrange, \yrange)}
\else
  \pgfmathsetmacro{\figscale}{6 / \vieww}
\fi
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\pgfmathsetmacro{\loff}{0.34/\figscale}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
    % ===== 坐标系（showcoord=1 时绘制）=====
  \ifnum\showcoord>0
    \draw[->, thick] (\xleft-0.5, 0) -- (\xright+0.5, 0) node[right] {$x$};
    \draw[->, thick] (0, \ybottom-0.5) -- (0, \ytop+0.5) node[above] {$y$};
  \fi
  \coordinate (O) at (\cx,\cy);
  \coordinate (F1) at (\cx-\focal,\cy);
  \coordinate (F2) at (\cx+\focal,\cy);
  % 实轴/虚轴辅助线
  \ifnum\showaxes>0
    \draw[dashed, gray] (\cx-\xmax,\cy) -- (\cx+\xmax,\cy);
    \draw[dashed, gray] (\cx,\cy-\asymy) -- (\cx,\cy+\asymy);
  \fi
  % 渐近线 y=±(b/a)x
  \ifnum\showasymptotes>0
    \draw[thick, gray!60] (\cx-\xmax,\cy-\asymy) -- (\cx+\xmax,\cy+\asymy);
    \draw[thick, gray!60] (\cx-\xmax,\cy+\asymy) -- (\cx+\xmax,\cy-\asymy);
  \fi
  % 双曲线两条分支（右支 x>0，左支 x<0）；参数化 x=a·cosh(t), y=b·sinh(t)
  \draw[thick, domain=-1.45:1.45, samples=80, smooth] plot ({\cx+\semimajor*cosh(\x)},{\cy+\semiminor*sinh(\x)});
  \draw[thick, domain=-1.45:1.45, samples=80, smooth] plot ({\cx-\semimajor*cosh(\x)},{\cy+\semiminor*sinh(\x)});
  % 双曲线上点 P 连两焦点（双曲线定义 |PF1-PF2|=2a）
  \ifnum\showpoint>0
    \draw[thick] (F1) -- (\cx+\pointx,\cy+\rpy) -- (F2);
    \fill (\cx+\pointx,\cy+\rpy) circle [radius=\dotr pt];
    \node at ({\cx+1.16*\pointx},{\cy+1.16*\rpy}) {$\labelp$};
  \fi
  % 焦点 F1/F2
  \ifnum\showfoci>0
    \fill (F1) circle [radius=\dotr pt];
    \fill (F2) circle [radius=\dotr pt];
    \node[below left=3pt] at (F1) {$F_1$};
    \node[below right=3pt] at (F2) {$F_2$};
  \fi
  % 两个顶点 A1/A2（实轴端点）
  \ifnum\showvertices>0
    \fill (\cx-\semimajor,\cy) circle [radius=\dotr pt];
    \fill (\cx+\semimajor,\cy) circle [radius=\dotr pt];
    \node[above left=2pt] at (\cx-\semimajor,\cy) {$A_1$};
    \node[above right=2pt] at (\cx+\semimajor,\cy) {$A_2$};
  \fi
  % 中心 O
  \ifnum\showcenter>0
    \fill (O) circle [radius=\dotr pt];
    \node[below right=2pt] at (O) {$O$};
  \fi
\end{tikzpicture}
